//! 🌊️ Writes named nodes, ordered parameters, exact coordinates and independent edge ports.
use crate::standards::v1::subsets::flow::schema::snapshot::{SemioFlowSnapshot,FlowNode,FlowParam,FlowEdge,PortRef};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_encoding::{self,Writer};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl,ValueError};
pub(crate) fn encode(snapshot:&SemioFlowSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,ValueError>{native_encoding::encode_admitted(encoding,"semio stdio.semio.flow.dsl v1\n","stdio.semio.flow.pack v1",control,|control|crate::standards::v1::subsets::flow::io::sqlite::snapshot::admit_values(snapshot,store::sqlite_snapshot::SqliteSnapshotPhase::EncodeNative,control),|writer,encoding|fields(snapshot,writer,encoding))}
fn parameter(value:&FlowParam,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.key,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.value,encoding)?;writer.delimiter(b"]",encoding)}
fn node(value:&FlowNode,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.kind,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.label,encoding)?;writer.delimiter(b",",encoding)?;writer.list(&value.params,encoding,|writer,value|parameter(value,writer,encoding))?;writer.delimiter(b",[",encoding)?;writer.number(value.position.x,encoding)?;writer.delimiter(b",",encoding)?;writer.number(value.position.y,encoding)?;writer.delimiter(b"]]",encoding)}
fn port(value:&PortRef,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.node,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.port,encoding)?;writer.delimiter(b"]",encoding)}
fn edge(value:&FlowEdge,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;port(&value.from,writer,encoding)?;writer.delimiter(b",",encoding)?;port(&value.to,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.kind,encoding)?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioFlowSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?;}else{writer.bytes(b"schema=")?;}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nnodes=",encoding)?;writer.list(&snapshot.nodes,encoding,|writer,value|node(value,writer,encoding))?;writer.delimiter(b"\nedges=",encoding)?;writer.list(&snapshot.edges,encoding,|writer,value|edge(value,writer,encoding))}
